"""Mutalia-e-Quran XII PDF173: p.170 — Surah al-Hadid heading; verses 57:1–7 (57:8 continues onto p.171; recorded there). Run: python class12_quran_page173.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p173():
    b = Builder()
    b.h('Surah al-Hadid (57) — Madani; order of revelation 94; verses 29, sections 4', 'سُوْرَةُ الْحَدِيْدِ ۵۷ — مَدَنِيَّةٌ ۹۴ — اٰیَاتُهَا ۲۹، رُکُوْعَاتُهَا ۴', 'سورة الحدید (۵۷) — مدني؛ د نزول ترتیب ۹۴؛ آیتونه ۲۹، رکوعونه ۴')
    b.p('بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nIn the name of Allah, the Beneficent, the Merciful.', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nاللہ کے نام سے شروع جو بڑا مہربان نہایت رحم فرمانے والا ہے', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\nد الله په نوم پیل چې ډېر مهربان، بې‌حده رحم کوونکی دی')
    b.paras[-1]['arabicSource'] = True
    V(b, 57, 1, 'اللہ کی تسبیح کی ہر اس چیز نے جو بھی آسمانوں اور زمینوں میں ہے اور وہ بہت غالب بڑی حکمت والا ہے۔',
      'د الله تسبیح یې ووېله هر هغه شي چې په آسمانونو او ځمکو کې دی؛ او هغه ډېر غالب، ډېر حکمتناک دی.')
    V(b, 57, 2, 'اُسی کے لیے آسمانوں اور زمینوں کی بادشاہت ہے وہی زندگی دیتا اور (وہی) موت دیتا ہے اور وہ ہر چیز پر بڑی قدرت رکھنے والا ہے۔',
      'د آسمانونو او ځمکو پاچاهي د هماغه ده؛ همغه ژوند ورکوي او (همغه) مرګ ورکوي؛ او هغه پر هر شي لوی قدرت لرونکی دی.')
    V(b, 57, 3, 'وہی اول بھی ہے اور آخر بھی اور (وہی) ظاہر بھی ہے اور باطن بھی اور وہ ہر چیز کو خوب جاننے والا ہے۔',
      'همغه لومړی هم دی او وروستی هم، او (همغه) ښکاره هم دی او پټ هم؛ او هغه په هر شي ښه پوه دی.')
    V(b, 57, 4, 'وہی ہے جس نے آسمانوں اور زمینوں کو چھے دنوں میں پیدا فرمایا پھر (اپنی شان کے مطابق) عرش پر جلوہ افروز ہوا وہ جانتا ہے جو زمین میں داخل ہوتا ہے اور جو اس میں سے نکلتا ہے اور جو آسمان سے نازل ہوتا ہے اور جو اس میں چڑھتا ہے اور تم جہاں کہیں بھی ہو وہ تمھارے ساتھ ہوتا ہے اور جو تم کر رہے ہو اللہ اُسے خوب دیکھنے والا ہے۔',
      'همغه دی چې آسمانونه او ځمکې یې په شپږو ورځو کې پیدا کړې، بیا (د خپل شان سره سم) پر عرش مستوي شو؛ هغه پوهېږي څه چې ځمکې ته ننوځي او څه چې ترې راوځي، او څه چې له آسمانه نازلېږي او څه چې ورته ختي؛ او تاسو چې هر چېرې یاست هغه له تاسو سره دی؛ او څه چې تاسو کوئ، الله یې ښه لیدونکی دی.')
    V(b, 57, 5, 'اُسی کے لیے آسمانوں اور زمینوں کی بادشاہت ہے اور تمام کام اللہ ہی کی طرف لوٹائے جاتے ہیں۔',
      'د آسمانونو او ځمکو پاچاهي د هماغه ده، او ټولې چارې یوازې الله ته ورګرځول کېږي.')
    V(b, 57, 6, 'وہ رات کو دن میں داخل فرماتا ہے اور دن کو رات میں داخل فرماتا ہے اور وہ سینوں کے رازوں کو بھی خوب جاننے والا ہے۔',
      'هغه شپه په ورځ کې ننباسي او ورځ په شپه کې ننباسي؛ او هغه د سینو په رازونو هم ښه پوه دی.')
    V(b, 57, 7, 'اللہ پر اور اس کے رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) پر ایمان لاؤ اور اس میں سے خرچ کرو جس میں اُس نے تمھیں (پہلے لوگوں کا) جانشین بنایا ہے پس تم میں سے جو لوگ ایمان لائے اور انھوں نے (اللہ کی راہ میں) خرچ کیا تو ان کے لیے بہت بڑا اجر ہے۔',
      'پر الله او د هغه پر رسول (صلی الله علیه وعلی آله واصحابه وسلم) ایمان راوړئ، او له هغه څه چې تاسو یې پکې (د پخوانیو خلکو) ځایناستي کړي یاست، ولګوئ؛ نو له تاسو چې کومو کسانو ایمان راوړ او (د الله په لار کې) یې ولګول، د هغوی لپاره ډېر لوی اجر دی.')
    BOOK.save(173, [(18, rec(b, 18, 173, 173))], issues=[{'id': 'mq12-pdf173', 'unit': 18, 'printedPage': 170,
               'description': 'Surah cartouche: al-Hadid 57, Madaniyyah 94, ayat 29, ruku 4. Orange/yellow highlighter strokes by a reader on the basmala and verse 4 excluded. Verse 57:8 begins on the last line of p.170 and is recorded with p.171.'}])


if __name__ == '__main__':
    p173()
